const processed = [];

for (const item of $input.all()) {
  // Handle nested results array
  if (item.json.results && Array.isArray(item.json.results)) {
    for (const result of item.json.results) {
      const rawPrice = String(result.price ?? "").replace(/[$,]/g, "");
      const price = parseFloat(rawPrice);

      // Only add if price is valid and in range
      if (result.ticker && !isNaN(price) && price >= 15 && price <= 60) {
        processed.push({
          json: {
            ticker: result.ticker,
            price,
            ivCurrent: result.ivCurrent,
            ivRank: result.ivRank,
            iv52wkLow: result.iv52wkLow,
            iv52wkHigh: result.iv52wkHigh,
            ivChange: result.ivChange,
            ivDirection: result.ivDirection,
            rv30d: result.rv30d,
