const results = [];

for (const item of items) {
  const data   = item.json;
  const ticker = data.ticker;
  const spot   = Number(data.spotPrice) || 0;
  const calls  = Array.isArray(data.calls) ? data.calls : [];

  if (!spot || calls.length === 0) {
    results.push({
      json: {
        ticker,
        reason:    "Missing spot price or no calls returned",
        spotPrice: spot,
        callCount: calls.length,
      },
    });
    continue;
  }

  for (const call of calls) {
    const strike = Number(call.strike) || 0;
    const bid    = Number(call.bid ?? 0);
    const ask    = Number(call.ask ?? 0);
    const oi     = Number(call.openInterest ?? 0);
    const volume = Number(call.volume ?? 0);
    const iv     = Number(call.impliedVolatility ?? 0);

    // basic filters
    if (!strike) continue;
    if (strike < spot) continue;

    // choose premium: prefer ask, then bid
    const premium = ask || bid || 0;
    if (premium <= 0) continue;

    // core ratios (keep as pure numbers here)
    const premiumYield = spot > 0 ? `${((premium / spot) * 100).toFixed(1)}%` : "0.0%";            // e.g. 0.10 = 10%

    const upsidePct = spot > 0 ? `${(((strike - spot) / spot) * 100).toFixed(1)}%` : "0.0%";    // 0.13 = 13% upside

    const totalIfCalled = spot > 0 ? `${(((premium / spot)  + ((strike - spot) / spot)) * 100).toFixed(1)}%` :"0.0%" ;                 // 0.23 = 23%

    // bid/ask spread as fraction (0.2 = 20%) or null if not computable
    const spreadPct = (ask > 0 && bid > 0)
      ? `${(((ask - bid) / ask) * 100).toFixed(1)}%`
      : null;

    results.push({
      json: {
        ticker,
        expir:             call.expiration || null,
        spotPrice:         spot,
        strike,
        bid,
        ask,
        premium,
        premiumYield,      // ratio, not formatted
        upsidePct,         // ratio, not formatted
        totalIfCalled,     // ratio, not formatted
        openInterest:      oi,
        volume,
        impliedVolatility: `${iv.toFixed(2)}%`,
        spreadPct,         // ratio (e.g. 0.8 = 80%), not formatted
      },
    });
  }
}

return results;

